```sql
/* Выбираем рестораны формата "buffet" и "coffee shop", работающие в интервале 07:30–16:00 */
SELECT
    r."name",
    r."service_format",
    r."hours"
FROM "restaurant" r
WHERE LOWER(r."service_format") IN ('buffet', 'coffee shop')
  /* Проверяем, что время открытия не позже 07:30 и время закрытия не раньше 16:00 */
  AND (
      /* Извлекаем время открытия и закрытия из текстового поля hours */
      (regexp_match(r."hours", '(\d{1,2}:\d{2})'))[1]::time <= '07:30'::time
      AND (regexp_match(r."hours", '(\d{1,2}:\d{2})\s*[^0-9]*$'))[1]::time >= '16:00'::time
  )
ORDER BY r."service_format", r."name";
```

```sql
/* Список описаний блюд на вынос (takeaway) с любой датой "годен до" */
/* и описаний готовых блюд (prepared) с датой "годен до" 10.11.2018 */
SELECT
    m."description",
    m."bestbefore"
FROM "meals" AS m
WHERE
    /* takeaway — любая дата */
    (LOWER(m."mealtype") = 'takeaway')
    OR
    /* prepared — конкретная дата, приведённая к типу DATE */
    (LOWER(m."mealtype") = 'prepared'
     AND m."bestbefore"::DATE = DATE '2018-11-10');
```

