```sql
/* Find functions assigned to every HR professional (common to all) */
SELECT f."functionid", f."description"
FROM "functions" f
JOIN "hr_professionals_functions" hpf ON hpf."functionid" = f."functionid"
GROUP BY f."functionid", f."description"
HAVING COUNT(DISTINCT hpf."hrprofessionalid") = (
    SELECT COUNT(DISTINCT "id") FROM "hr_professionals"
);
```

```sql
/* Находим системы, которые поддерживаются всеми IT-специалистами (общие для всех) */
SELECT
    s."system_name",
    s."is_active"
FROM "systems" AS s
JOIN "it_support_specialists_systems" AS iss ON iss."system_id" = s."system_id"
GROUP BY s."system_id", s."system_name", s."is_active"
/* Оставляем только те системы, число уникальных специалистов по которым равно общему числу специалистов */
HAVING COUNT(DISTINCT iss."it_specialist_id") = (
    SELECT COUNT(DISTINCT "id") FROM "it_support_specialists"
);
```

